package canteen;
import javax.swing.*;import java.awt.*;import java.sql.*;import java.time.LocalDate;import java.util.*;
public class SalesChartPanel extends JPanel {
 private final java.util.List<String> days=new ArrayList<>();private final java.util.List<Double> values=new ArrayList<>();
 public SalesChartPanel(){setPreferredSize(new Dimension(340,190));setBackground(Color.WHITE);load();}
 private void load(){days.clear();values.clear();Map<String,Double> map=new HashMap<>();try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT DATE(order_date) d,COALESCE(SUM(final_total),0) sales FROM orders WHERE status='COMPLETED' AND order_date>=DATE_SUB(CURDATE(),INTERVAL 6 DAY) GROUP BY DATE(order_date)" );ResultSet r=p.executeQuery()){while(r.next())map.put(r.getDate("d").toString(),r.getDouble("sales"));}catch(SQLException e){setToolTipText("Sales chart unavailable: "+e.getMessage());}for(int i=6;i>=0;i--){LocalDate d=LocalDate.now().minusDays(i);days.add(d.getDayOfWeek().toString().substring(0,3));values.add(map.getOrDefault(d.toString(),0.0));}}
 @Override protected void paintComponent(Graphics g){super.paintComponent(g);Graphics2D a=(Graphics2D)g.create();a.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);a.setColor(AppStyle.NAVY);a.setFont(new Font("Segoe UI",Font.BOLD,13));a.drawString("Daily sales · last 7 days",12,20);int left=12,top=36,w=Math.max(200,getWidth()-24),h=Math.max(80,getHeight()-62);double max=1;for(double v:values)max=Math.max(max,v);a.setColor(new Color(226,233,244));a.drawLine(left,top+h,left+w,top+h);int slot=w/7;for(int i=0;i<values.size();i++){int bh=(int)(values.get(i)/max*(h-18));int x=left+i*slot+slot/4;int bw=Math.max(8,slot/2);a.setColor(AppStyle.BLUE);a.fillRoundRect(x,top+h-bh,bw,bh,6,6);a.setColor(AppStyle.MUTED);a.setFont(new Font("Segoe UI",Font.PLAIN,10));a.drawString(days.get(i),x-2,top+h+15);}a.dispose();}
}
